# Generated by Claude Fable 5.1 (Anthropic)
"""Single source of truth for the `nsys profile` flag set FISH uses.

Both wrapping paths — launch_wrap (composable-node containers, prefix at
execute-time) and the daemon's standalone-GPU-process relaunch
(gpu.build_nsys_command) — must produce the same profile, otherwise the
lttng+nsys mode observes different systems through different paths (v5
campaign, 2026-09-05: nodes the daemon relaunched with the full profile
produced no LTTng events; the same relaunch with this minimal profile was
fully traced; notes/aw_phases_provenance.md §7).

Lean set (2026-09-06, after reading the Nsight Systems user guide, CLI
profile switches): `nsys profile` turns CPU IP sampling (--sample) and
context-switch tracing (--cpuctxsw) ON by default whenever it launches a
target — the "minimal" --trace=cuda,nvtx profile of the v5/split campaigns
therefore still recorded 1.9 M SAMPLING_CALLCHAINS, 0.33 M SCHED_EVENTS and
0.32 M NVTX_EVENTS per apriltag run, none of which the model consumes. The
model reads exactly CUPTI RUNTIME, KERNEL, MEMCPY, MEMSET and
SYNCHRONIZATION (postprocess/ingest_pg.py, gpu_attribution.py, gpu_dag.py);
all of them come from --trace=cuda. Everything else is switched off
explicitly (defaults are version-dependent). The user guide flags these as
"significant runtime overhead": cudabacktrace, cuda-memory-usage,
cuda-um-*-page-faults, cuda-trace-all-apis, cuda-graph-trace=node,
cuda-event-trace ("may increase runtime overhead"), sampling frequency.
Opt-ins via env vars (identical on both wrapping paths):
  FISH_NSYS_NVTX=1            add nvtx to --trace (PyTorch/AAS ranges)
  FISH_CUDA_EVENT_TRACE=1     --cuda-event-trace=true (device-side events;
                              suspect in the 2026-09-06 GXF stalls)
  FISH_CUDA_GRAPH_NODE=1      --cuda-graph-trace=node
  FISH_CUDA_TRACE_ALL_APIS=1  --cuda-trace-all-apis=true
  FISH_NSYS_SAMPLE=1          --sample=process-tree --cpuctxsw=process-tree
                              (CPU sampling + scheduler trace, v5-style)
The full standalone profile (CUDA callchains for user-code attribution,
python backtrace/sampling + autograd NVTX for PyTorch nodes such as AAS
yolo_py, CPU sampling for SAMPLING_CALLCHAINS/SCHED_EVENTS, memory-usage
events, --stats) stays available for model-extraction runs as an explicit
opt-in — FISH_NSYS_STANDALONE_FULL=1 or [nsys] standalone_full = true —
and only on the standalone path (containers crash with it). These are
capture-time options: what is not recorded cannot be regenerated. Off for
overhead campaigns so both wrapping paths observe the system identically.
"""
import os


def _on(var: str) -> bool:
    return os.environ.get(var, "").lower() in ("1", "true", "yes")


def standalone_full_requested(settings=None) -> bool:
    if _on("FISH_NSYS_STANDALONE_FULL"):
        return True
    try:
        return settings is not None and settings.getboolean("nsys", "standalone_full")
    except Exception:
        return False


def standalone_extra_flags(settings) -> list[str]:
    """The April-2026 full profile for standalone GPU nodes, values from
    [nsys] in fish_settings.ini (gpu_profiling_journey.txt §5)."""
    g = lambda k: settings.get("nsys", k)
    return [
        f"--cuda-memory-usage={g('cuda_memory_usage')}",
        f"--cudabacktrace={g('cudabacktrace')}",
        f"--python-backtrace={g('python_backtrace')}",
        f"--python-sampling={g('python_sampling')}",
        f"--pytorch={g('pytorch')}",
        f"--sample={g('sample')}",
        f"--cpuctxsw={g('cpuctxsw')}",
        "--stats=true",
    ]


def base_nsys_flags() -> list[str]:
    trace = "cuda,nvtx" if _on("FISH_NSYS_NVTX") else "cuda"
    sample = "process-tree" if _on("FISH_NSYS_SAMPLE") else "none"
    flags = [
        "nsys", "profile",
        f"--trace={trace}",
        f"--sample={sample}",
        f"--cpuctxsw={sample}",
        "--backtrace=none",
        "--cudabacktrace=none",
        "--cuda-memory-usage=false",
        "--cuda-um-cpu-page-faults=false",
        "--cuda-um-gpu-page-faults=false",
        "--cuda-event-trace=" + ("true" if _on("FISH_CUDA_EVENT_TRACE") else "false"),
        "--cuda-graph-trace=" + ("node" if _on("FISH_CUDA_GRAPH_NODE") else "graph"),
        "--cuda-trace-all-apis=" + ("true" if _on("FISH_CUDA_TRACE_ALL_APIS") else "false"),
        "--gpu-metrics-devices=none",
        "--stats=false",
        "--export=sqlite",
        "--force-overwrite=true",
    ]
    return flags
